  // خرائط لغة التطبيق إلى كود اللغة اللي هيتبعت لـ Nominatim (OpenStreetMap)
  // عشان اسم الموقع (المدينة/القرية) يرجع بنفس لغة الواجهة قدر الإمكان
  var NOMINATIM_LANG = { ar: 'ar', fa: 'fa', en: 'en', fr: 'fr', tr: 'tr', ur: 'ur', id: 'id', ru: 'ru', es: 'es' };

  var languageChangeListeners = [];
  function onLanguageChange(fn) {
    if (typeof fn === 'function') languageChangeListeners.push(fn);
  }
  function notifyLanguageChange(lang) {
    languageChangeListeners.forEach(function (fn) {
      try { fn(lang); } catch (e) { /* تجاهل */ }
    });
  }

  function getHijriMonthName(monthNumber, lang) {
    var cal = CALENDAR[lang] || CALENDAR[DEFAULT_LANG];
    return cal.months[(monthNumber - 1 + 12) % 12] || '';
  }
  function getWeekdayName(enName, lang) {
    var cal = CALENDAR[lang] || CALENDAR[DEFAULT_LANG];
    return (cal.weekdays && cal.weekdays[enName]) || enName || '';
  }
  function getHijriEra(lang) {
    var cal = CALENDAR[lang] || CALENDAR[DEFAULT_LANG];
    return cal.era;
  }
  function getNominatimLang(lang) {
    return NOMINATIM_LANG[lang] || 'en';
  }

  // بتحاول تلاقي لغة الجهاز (من إعدادات النظام/المتصفح) ضمن اللغات
  // المدعومة في التطبيق؛ بتتجاهل كود الدولة (زي "en-US" ← "en") وبتاخد
  // أول لغة من قايمة تفضيلات الجهاز فعلاً مدعومة عندنا. لو ملقتش حاجة
  // مطابقة، بترجع للعربية (اللغة الافتراضية) زي ما كان قبل كده
  function detectDeviceLang() {
    try {
      var prefs = (navigator.languages && navigator.languages.length)
        ? navigator.languages
        : [navigator.language || navigator.userLanguage || ''];
      for (var i = 0; i < prefs.length; i++) {
        var code = String(prefs[i] || '').toLowerCase().split('-')[0];
        if (T[code]) return code;
      }
    } catch (e) { /* تجاهل */ }
    return DEFAULT_LANG;
  }

  function getSavedLang() {
    try {
      var saved = localStorage.getItem(STORAGE_KEY);
      if (saved && T[saved]) return saved;
    } catch (e) {}
    // مفيش لغة محفوظة (أول تشغيل، أو المستخدم مسحش الإعدادات) ← نجرّب
    // نطابق لغة الجهاز نفسه، وميتغيّرش تاني إلا لو المستخدم بنفسه اختار
    // لغة من شاشة الإعدادات (وقتها بتتخزن في setLanguage وتتفضّل)
    return detectDeviceLang();
  }

  function t(lang, key) {
    return (UPDATE_PAGE_EXTRA[lang] && UPDATE_PAGE_EXTRA[lang][key]) || (UPDATE_EXTRA[lang] && UPDATE_EXTRA[lang][key]) || (UPDATE_DIALOG_EXTRA[lang] && UPDATE_DIALOG_EXTRA[lang][key]) || (T[lang] && T[lang][key]) || (TOUR_EXTRA[lang] && TOUR_EXTRA[lang][key]) || (NAV_EXTRA[lang] && NAV_EXTRA[lang][key]) || (EXTRA[lang] && EXTRA[lang][key]) || (UPDATE_PAGE_EXTRA.en && UPDATE_PAGE_EXTRA.en[key]) || (UPDATE_EXTRA.en && UPDATE_EXTRA.en[key]) || (UPDATE_DIALOG_EXTRA.en && UPDATE_DIALOG_EXTRA.en[key]) || (T.en && T.en[key]) || (TOUR_EXTRA.en && TOUR_EXTRA.en[key]) || (NAV_EXTRA.en && NAV_EXTRA.en[key]) || (EXTRA.en && EXTRA.en[key]) || (UPDATE_PAGE_EXTRA[DEFAULT_LANG] && UPDATE_PAGE_EXTRA[DEFAULT_LANG][key]) || (UPDATE_EXTRA[DEFAULT_LANG] && UPDATE_EXTRA[DEFAULT_LANG][key]) || (UPDATE_DIALOG_EXTRA[DEFAULT_LANG] && UPDATE_DIALOG_EXTRA[DEFAULT_LANG][key]) || (T[DEFAULT_LANG] && T[DEFAULT_LANG][key]) || (TOUR_EXTRA[DEFAULT_LANG] && TOUR_EXTRA[DEFAULT_LANG][key]) || (NAV_EXTRA[DEFAULT_LANG] && NAV_EXTRA[DEFAULT_LANG][key]) || (EXTRA[DEFAULT_LANG] && EXTRA[DEFAULT_LANG][key]) || key;
  }

